-- Incoming supplier-defect backlog (To Do, untriaged). Reporter = PM.
INSERT INTO issues (id, key, project_key, type_id, summary, description, status_id, priority_id, assignee, reporter, labels_json, components_json, resolution, created_at, updated_at) VALUES
  ('100001', 'PROJ-1', 'PROJ', '10002', 'Power bank pack distends until the shell separates', 'SKU NB-PWRBANK-P3 (20,000 mAh power bank); supplier Dongguan CellWorks.
Severity: Critical. Affected units: 1500 (out of a 4000-unit production run). Regulatory status: not reportable.
Symptom: After about ten quick-charge cycles the internal pack distends until the two halves of the enclosure spring apart at the seam; one returned unit was still noticeably warm the next morning, long after it had been unplugged.
Root cause: the cells in this consignment build up gas inside during quick charging — the cell maker confirmed an out-of-spec internal divider film.
Story points: 5.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T09:00:00.000Z', '2026-05-25T09:00:00.000Z'),
  ('100002', 'PROJ-2', 'PROJ', '10002', 'Cable sheath develops splits and bares the conductor', 'SKU NB-CABLE-L4 (USB-C charge cable); supplier Shenzhen BrightCord.
Severity: Critical. Affected units: 900 (out of a 6000-unit production run). Regulatory status: not reportable.
Symptom: Within roughly a week of ordinary use the outer sheath develops fine lengthwise splits and the bare copper underneath shows through; one user felt a faint tingle plugging it in with damp hands.
Root cause: the sheath compound from this extrusion run is too brittle and fails the repeated-bend endurance test.
Story points: 5.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T10:00:00.000Z', '2026-05-25T10:00:00.000Z'),
  ('100003', 'PROJ-3', 'PROJ', '10002', 'Charger body reaches about 70 C under a sustained load', 'SKU NB-CHARGER-Q5 (65 W fast charger); supplier Xiamen VoltPlus.
Severity: Major. Affected units: 600 (out of a 5000-unit production run). Regulatory status: not reportable.
Symptom: During a long charging session the body of the unit climbs to roughly 70 C — enough to leave a dull scorch ring on a wooden desk and to sting fingers pressed against it.
Root cause: the quick-charge regulator chip on the board runs far past its rated temperature.
Story points: 3.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T11:00:00.000Z', '2026-05-25T11:00:00.000Z'),
  ('100004', 'PROJ-4', 'PROJ', '10002', 'Earbuds drop audio past roughly two metres', 'SKU NB-EARBUD-X1 (wireless earbuds); supplier Ningbo SoundLab.
Severity: Minor. Affected units: 800 (out of a 3000-unit production run). Regulatory status: not reportable.
Symptom: The sound chops out as soon as the handset is more than about two metres away and returns the moment you step back in close; the pairing itself never lets go.
Root cause: a range regression introduced by the v2.1 wireless firmware.
Story points: 4.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T12:00:00.000Z', '2026-05-25T12:00:00.000Z'),
  ('100005', 'PROJ-5', 'PROJ', '10002', 'Watch screen goes dark for a few seconds at random', 'SKU NB-WATCH-W6 (smartwatch); supplier Foshan WearTech.
Severity: Major. Affected units: 300 (out of a 2500-unit production run). Regulatory status: not reportable.
Symptom: The display goes completely dark for a few seconds at unpredictable moments and then comes back on its own; nothing else about the watch misbehaves.
Root cause: the display ribbon connector is not fully seated in its socket.
Story points: 3.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T13:00:00.000Z', '2026-05-25T13:00:00.000Z'),
  ('100006', 'PROJ-6', 'PROJ', '10002', 'Soft-touch coating sheds off the back of the case', 'SKU NB-CASE-C5 (protective phone case); supplier Quanzhou MoldRight.
Severity: Minor. Affected units: 250 (out of a 6000-unit production run). Regulatory status: not reportable.
Symptom: The soft-touch coating on the back starts shedding in patches within a few weeks, leaving the plain plastic showing through; the case still clips on and protects the phone as intended.
Root cause: the coating is not bonding to the substrate on this batch.
Story points: 3.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T14:00:00.000Z', '2026-05-25T14:00:00.000Z'),
  ('100007', 'PROJ-7', 'PROJ', '10002', 'One hub port drops out at the slightest movement', 'SKU NB-HUB-H7 (7-port USB hub); supplier Ningbo PortPlus.
Severity: Minor. Affected units: 100 (out of a 3000-unit production run). Regulatory status: not reportable.
Symptom: One of the ports drops whatever is plugged in at the smallest nudge of the cable, while the remaining ports stay rock solid; transfers are fine right up until the drop.
Root cause: a cold solder joint on that one port''s data pads.
Story points: 2.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T15:00:00.000Z', '2026-05-25T15:00:00.000Z'),
  ('100008', 'PROJ-8', 'PROJ', '10002', 'Desk fan blades stop until you give it a tap', 'SKU NB-FAN-F2 (USB desk fan); supplier Foshan AirFlow.
Severity: Minor. Affected units: 99 (out of a 2000-unit production run). Regulatory status: not reportable.
Symptom: The blades quit turning at random moments and start again only if you tap the housing, after which it runs for a while; it stays cool and makes no unusual noise.
Root cause: a sticky sleeve bearing in a sub-batch of motors.
Story points: 2.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T16:00:00.000Z', '2026-05-25T16:00:00.000Z'),
  ('100009', 'PROJ-9', 'PROJ', '10002', 'Travel adapter feels warm to the touch in use', 'SKU NB-ADAPTER-A3 (universal travel adapter); supplier Xiamen VoltPlus.
Severity: Minor. Affected units: 150 (out of a 2500-unit production run). Regulatory status: not reportable.
Symptom: Several buyers say the adapter feels warmer than they expected in use; a bench check put it at about 41 C, comfortably inside its stated rating, and it keeps working normally.
Root cause: ordinary conversion loss in a slightly undersized internal heat spreader.
Story points: 2.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-25T17:00:00.000Z', '2026-05-25T17:00:00.000Z'),
  ('100010', 'PROJ-10', 'PROJ', '10002', 'Adapter can flash over internally when the mains surges', 'SKU NB-ADAPTER-V8 (AC power adapter); supplier Xiamen VoltPlus.
Severity: Major. Affected units: 250 (out of a 3000-unit production run). Regulatory status: reportable.
Symptom: When the mains supply spikes, the adapter can flash over internally with an audible snap; an inspection found scorch marks across the board around the input stage.
Root cause: the surge-clamping component on the input is undersized for the spikes seen on site.
Story points: 4.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-26T09:00:00.000Z', '2026-05-26T09:00:00.000Z'),
  ('100011', 'PROJ-11', 'PROJ', '10002', 'Left earbud often will not charge in its case', 'SKU NB-EARBUD-X1 (wireless earbuds); supplier Ningbo SoundLab.
Severity: Minor. Affected units: 120 (out of a 3000-unit production run). Regulatory status: not reportable.
Symptom: The left bud frequently fails to take any charge when it is set in the case, while the right bud charges every time; reseating it sometimes helps for one session.
Root cause: a weak charging-contact spring on the left side of the case.
Story points: 3.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-26T10:00:00.000Z', '2026-05-26T10:00:00.000Z'),
  ('100012', 'PROJ-12', 'PROJ', '10002', 'Some earbud shells arrive with a hairline crack', 'SKU NB-EARBUD-X1 (wireless earbuds); supplier Ningbo SoundLab.
Severity: Minor. Affected units: 90 (out of a 3000-unit production run). Regulatory status: not reportable.
Symptom: A portion of units arrive with a faint hairline crack running across the outer shell; the buds still pair, charge, and play exactly as they should.
Root cause: a fine crack forming in the shell as it is released from the mould.
Story points: 2.', '1', NULL, '', 'pm@northbridge.example.com', '[]', '[]', '', '2026-05-26T11:00:00.000Z', '2026-05-26T11:00:00.000Z'),
  ('100013', 'PROJ-13', 'PROJ', '10002', 'Required conformity marking missing from the case label', 'SKU NB-CASE-C2 (protective phone case); supplier Quanzhou MoldRight.
Severity: Minor. Affected units: 800 (out of a 6000-unit production run). Regulatory status: reportable.
